# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">YAŞADIĞIMIZ İLDE GÖRÜLEBİLECEK BAŞLICA AFETLER VE ÖNLEMLER</text>\n  <rect x="18" y="46" width="212" height="194" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="124" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Jeolojik Afetler (Yer Kökenli)</text>\n  <text x="124" y="94" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">• DEPREM (Yer Sarsıntısı)</text>\n  <text x="124" y="114" text-anchor="middle" font-size="11" fill="#334155">Fay hatları üzerinde oluşur.</text>\n  <text x="124" y="132" text-anchor="middle" font-size="11" fill="#1e293b">Önlem: Sağlam zemin, depreme</text>\n  <text x="124" y="148" text-anchor="middle" font-size="11" fill="#1e293b">dayanıklı bina, eşya sabitleme.</text>\n  <text x="124" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">• HEYELAN (Toprak Kayması)</text>\n  <text x="124" y="194" text-anchor="middle" font-size="11" fill="#334155">Eğimli, yağışlı ve killi yamaçlar.</text>\n  <text x="124" y="212" text-anchor="middle" font-size="11" fill="#1e293b">Önlem: İstinat duvarı, ağaçlandırma,</text>\n  <text x="124" y="228" text-anchor="middle" font-size="11" fill="#1e293b">yamaç eteklerine bina yapmama.</text>\n\n  <rect x="244" y="46" width="212" height="194" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Klimatolojik-Hidrolojik Afetler</text>\n  <text x="350" y="94" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• SEL VE TAŞKIN</text>\n  <text x="350" y="114" text-anchor="middle" font-size="11" fill="#334155">Aşırı yağış ve dere yatağı daralması.</text>\n  <text x="350" y="132" text-anchor="middle" font-size="11" fill="#1e293b">Önlem: Dere yataklarına ev yapmama,</text>\n  <text x="350" y="148" text-anchor="middle" font-size="11" fill="#1e293b">altyapı ıslahı ve yeşil alanları koruma.</text>\n  <text x="350" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• ÇIĞ (Kar Kütlelerinin Kayması)</text>\n  <text x="350" y="194" text-anchor="middle" font-size="11" fill="#334155">Dik ve kar yağışlı dağlık yamaçlar.</text>\n  <text x="350" y="212" text-anchor="middle" font-size="11" fill="#1e293b">Önlem: Çığ perdeleri, ağaçlandırma,</text>\n  <text x="350" y="228" text-anchor="middle" font-size="11" fill="#1e293b">dik yamaçlarda gürültüden kaçınma.</text>\n\n  <rect x="470" y="46" width="212" height="194" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="576" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Biyolojik ve İnsan Kaynaklı</text>\n  <text x="576" y="94" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">• ORMAN YANGINI</text>\n  <text x="576" y="114" text-anchor="middle" font-size="11" fill="#334155">Yaz kuraklığı + insan ihmali (%90).</text>\n  <text x="576" y="132" text-anchor="middle" font-size="11" fill="#1e293b">Önlem: Ormanda ateş yakmama, cam</text>\n  <text x="576" y="148" text-anchor="middle" font-size="11" fill="#1e293b">kırığı bırakmama, Alo 112 ihbarı.</text>\n  <text x="576" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">• EROZYON (Toprak Aşınması)</text>\n  <text x="576" y="194" text-anchor="middle" font-size="11" fill="#334155">Verimli üst toprağın süpürülmesi.</text>\n  <text x="576" y="212" text-anchor="middle" font-size="11" fill="#1e293b">Önlem: Nöbetleşe ekim, teraslama,</text>\n  <text x="576" y="228" text-anchor="middle" font-size="11" fill="#1e293b">ağaçlandırma, anız yakmama.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">AFET BİLİNCİ: AFET ÖNCESİ, SIRASI VE SONRASI ADIMLAR</text>\n  <rect x="20" y="46" width="210" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">1. AFET ÖNCESİ (Hazırlık)</text>\n  <text x="125" y="96" text-anchor="middle" font-size="11" fill="#1e293b">• Aile Afet ve Acil Durum Planı</text>\n  <text x="125" y="118" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">• Afet ve Acil Durum Çantası</text>\n  <text x="125" y="136" text-anchor="middle" font-size="10" fill="#334155">(Su, kuru gıda, ilk yardım çantası,</text>\n  <text x="125" y="152" text-anchor="middle" font-size="10" fill="#334155">el feneri, düdük, radyo, pil, ilaç)</text>\n  <text x="125" y="176" text-anchor="middle" font-size="11" fill="#1e293b">• Dolap ve ağır eşyaları duvara</text>\n  <text x="125" y="194" text-anchor="middle" font-size="11" fill="#1e293b">sabitleme (L-demir aparatı)</text>\n  <text x="125" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">• Toplanma alanını öğrenme</text>\n\n  <rect x="245" y="46" width="210" height="192" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">2. AFET SIRASI (Doğru Davranış)</text>\n  <text x="350" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">• Depremde: ÇÖK - KAPAN - TUTUN!</text>\n  <text x="350" y="118" text-anchor="middle" font-size="11" fill="#1e293b">Sağlam bir eşyanın yanında yaşam</text>\n  <text x="350" y="136" text-anchor="middle" font-size="11" fill="#1e293b">üçgeni oluşturarak başı koruma.</text>\n  <text x="350" y="160" text-anchor="middle" font-size="11" font-weight="bold" fill="#dc2626">• Asansör, balkon ve merdivenlerden</text>\n  <text x="350" y="178" text-anchor="middle" font-size="11" font-weight="bold" fill="#dc2626">uzak durma, panik yapmama.</text>\n  <text x="350" y="204" text-anchor="middle" font-size="11" fill="#1e293b">• Sel sırasında: Çukur yerlerden ve</text>\n  <text x="350" y="222" text-anchor="middle" font-size="11" fill="#1e293b">su birikintilerinden yükseğe çıkma.</text>\n\n  <rect x="470" y="46" width="210" height="192" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">3. AFET SONRASI (Tahliye)</text>\n  <text x="575" y="96" text-anchor="middle" font-size="11" fill="#1e293b">• Sarsıntı durunca elektrik, su ve</text>\n  <text x="575" y="114" text-anchor="middle" font-size="11" fill="#1e293b">doğal gaz vanalarını kapatma.</text>\n  <text x="575" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">• Afet çantasını alıp güvenli</text>\n  <text x="575" y="156" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">toplanma alanına gitme.</text>\n  <text x="575" y="180" text-anchor="middle" font-size="11" fill="#1e293b">• Hasarlı binalara girmeme, telefon</text>\n  <text x="575" y="198" text-anchor="middle" font-size="11" fill="#1e293b">hatlarını gereksiz meşgul etmeme.</text>\n  <text x="575" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">• AFAD ve 112 duyurularını izleme.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">AFET FARKINDALIK EYLEM PLANI VE İLGİLİ KURUMLAR</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Farkındalık Etkinliği Planlama Aşamaları</text>\n  <text x="182" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">1. Planlama (Hazırlık):</text>\n  <text x="182" y="118" text-anchor="middle" font-size="11" fill="#334155">İlimizdeki öncelikli afet riskini belirleme, amaç,</text>\n  <text x="182" y="134" text-anchor="middle" font-size="11" fill="#334155">hedef kitle ve görev dağılımını oluşturma.</text>\n  <text x="182" y="158" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">2. Uygulama (Eyleme Dönüştürme):</text>\n  <text x="182" y="176" text-anchor="middle" font-size="11" fill="#334155">Tahliye tatbikatı, afet çantası tanıtımı, bilgi</text>\n  <text x="182" y="192" text-anchor="middle" font-size="11" fill="#334155">panosu ve seminer etkinliğini gerçekleştirme.</text>\n  <text x="182" y="216" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">3. Değerlendirme: Güçlü yönleri analiz etme.</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Afet ve Acil Durum Kurumları</text>\n  <text x="517" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• AFAD (Afet ve Acil Durum Yönetimi Bşk.)</text>\n  <text x="517" y="120" text-anchor="middle" font-size="11" fill="#334155">Afet öncesi hazırlık ve kurtarma koordinasyonu</text>\n  <text x="517" y="146" text-anchor="middle" font-size="12" font-weight="bold" fill="#dc2626">• TÜRK KIZILAYI</text>\n  <text x="517" y="166" text-anchor="middle" font-size="11" fill="#334155">Barınma (çadır), beslenme, kan ve insani yardım</text>\n  <text x="517" y="192" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">• TEMA &amp; Orman Genel Müdürlüğü</text>\n  <text x="517" y="212" text-anchor="middle" font-size="11" fill="#334155">Ağaçlandırma, erozyon ve orman yangınıyla mücadele</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
